import 'dart:typed_data';
import 'package:supabase_flutter/supabase_flutter.dart';
import '../domain/lifecycle_models.dart';
class LifecycleRepository {
 LifecycleRepository({SupabaseClient? client}):db=client??Supabase.instance.client;
 final SupabaseClient db;
 String get authId=>db.auth.currentUser?.id??(throw StateError('Please sign in again.'));
 Future<String> get employeeId async=>(await db.from('users').select('id').eq('auth_user_id',authId).single())['id'].toString();
 Future<List<EmployeeOption>> employees() async {final rows=await db.from('users').select('id,name,agent_code').eq('status','active').eq('employment_status','ACTIVE').eq('id_approval_status','APPROVED').order('name');return rows.map((r)=>EmployeeOption.fromJson(Map<String,dynamic>.from(r))).toList();}
 Future<List<LifecycleRow>> rows(String table,{String? order}) async {final q=order==null?db.from(table).select('*'):db.from(table).select('*').order(order,ascending:false);final r=await q;return r.map((x)=>LifecycleRow.fromJson(Map<String,dynamic>.from(x))).toList();}
 Future<Map<String,dynamic>> issueId(String id) async {final r=await db.rpc('issue_employee_id_card',params:{'p_employee_id':id});if(r is List&&r.isNotEmpty)return Map<String,dynamic>.from(r.first as Map);if(r is Map)return Map<String,dynamic>.from(r);throw StateError('Empty ID card response.');}
 Future<Map<String,dynamic>> verifyQr(String token) async {final r=await db.rpc('verify_employee_qr',params:{'p_token':token});if(r is List&&r.isNotEmpty)return Map<String,dynamic>.from(r.first as Map);throw StateError('QR code not recognized.');}
 Future<void> uploadDocument(String type,String name,Uint8List bytes,String mime) async {if(bytes.isEmpty||bytes.length>25*1024*1024)throw const FormatException('Document must be 25 MB or smaller.');final id=await employeeId;final path=id+'/'+DateTime.now().microsecondsSinceEpoch.toString()+'_'+name.replaceAll(RegExp(r'[^A-Za-z0-9._-]'),'_');await db.storage.from('employee-documents').uploadBinary(path,bytes,fileOptions:FileOptions(contentType:mime,upsert:false));try{await db.from('employee_documents').insert({'employee_id':id,'document_type':type,'file_path':path,'file_name':name,'mime_type':mime,'file_size_bytes':bytes.length,'status':'pending'});}catch(_){await db.storage.from('employee-documents').remove([path]);rethrow;}}
 Future<String> documentUrl(String path)=>db.storage.from('employee-documents').createSignedUrl(path,300);
 Future<void> reviewDocument(String id,bool approve,String note)=>db.rpc('review_employee_document',params:{'p_document_id':id,'p_decision':approve?'approved':'rejected','p_note':note.trim().isEmpty?null:note.trim()});
 Future<void> applyLeave(String type,DateTime start,DateTime end,String reason,String half) async {if(end.isBefore(start)||reason.trim().length<3)throw const FormatException('Check leave dates and enter a reason.');final id=await employeeId;final u=await db.from('users').select('team_id').eq('id',id).single();await db.from('leave_requests').insert({'user_id':id,'team_id':u['team_id'],'leave_type':type,'start_date':_date(start),'end_date':_date(end),'reason':reason.trim(),'days':type=='half_day'?0.5:(end.difference(start).inDays+1).toDouble(),'half_day_period':type=='half_day'?half:null});}
 Future<void> reviewLeave(String id,bool approve,String note)=>db.rpc('review_leave_request',params:{'p_leave_request_id':id,'p_decision':approve?'approved':'rejected','p_note':note.trim().isEmpty?null:note.trim()});
 Future<void> uploadLibraryFile({required String table,required String bucket,required String title,required String description,required String category,required String name,required Uint8List bytes,required String mime}) async {final limit=bucket=='dd-downloads'?50:100;if(bytes.isEmpty||bytes.length>limit*1024*1024)throw FormatException('File must be '+limit.toString()+' MB or smaller.');final id=await employeeId;final path=id+'/'+DateTime.now().microsecondsSinceEpoch.toString()+'_'+name.replaceAll(RegExp(r'[^A-Za-z0-9._-]'),'_');await db.storage.from(bucket).uploadBinary(path,bytes,fileOptions:FileOptions(contentType:mime,upsert:false));try{final data=table=='downloads'?{'title':title.trim(),'description':description.trim(),'category':category,'file_path':path,'file_name':name,'mime_type':mime,'file_size_bytes':bytes.length,'is_published':true,'uploaded_by':id}:{'title':title.trim(),'description':description.trim(),'product':category.split('|')[0],'material_type':category.split('|')[1],'file_path':path,'file_name':name,'mime_type':mime,'file_size_bytes':bytes.length,'is_published':true,'sort_order':0,'uploaded_by':id};await db.from(table).insert(data);}catch(_){await db.storage.from(bucket).remove([path]);rethrow;}}
 Future<String> openDownload(LifecycleRow f) async {final id=await employeeId;await db.from('download_history').insert({'download_id':f.id,'employee_id':id});return db.storage.from('dd-downloads').createSignedUrl(f.data['file_path'].toString(),300);}
 Future<String> openTraining(LifecycleRow f) async {final id=await employeeId;await db.from('training_views').upsert({'material_id':f.id,'employee_id':id,'viewed_at':DateTime.now().toUtc().toIso8601String()},onConflict:'material_id,employee_id');return db.storage.from('dd-training-materials').createSignedUrl(f.data['file_path'].toString(),300);}
 Future<void> completeTraining(String id) async {final e=await employeeId;await db.from('training_views').upsert({'material_id':id,'employee_id':e,'viewed_at':DateTime.now().toUtc().toIso8601String(),'completed_at':DateTime.now().toUtc().toIso8601String()},onConflict:'material_id,employee_id');}
 String _date(DateTime d)=>d.year.toString().padLeft(4,'0')+'-'+d.month.toString().padLeft(2,'0')+'-'+d.day.toString().padLeft(2,'0');
}
